Given a 2D mat of size n*n, print the matrix in the following pattern.Examples: Input: n = 2, mat[][] = [[1, 2],                        [3, 4]]Output: [1, 2, 3, 4]Explanation: Input: n = 3, mat[][] = [[1, 2, 3],                       [4, 5, 6],                       [7, 8, 9]]Output: [1, 2, 4, 3, 5, 7, 6, 8, 9]Explanation: Try It YourselfTable of Content[Naive Approach] Using Brute Force - O(n*n) Time and O(n*n) Space [Expected Approach] Using Direct Diagonal Traversal - O(n*n) Time and O(1) Space[Naive Approach] Using Brute Force - O(n*n) Time and O(n*n) Space The idea is to use the value of i + j, since elements with the same value lie on the same diagonal. We create a temporary array of arrays and store same diagonal elements at one place using (i+j) as index. Finally iterate over the temporary array to print the items diagonally.
            C++

    #include <iostream>
#include <vector>
using namespace std;

void diagonalTraversal(vector<vector<int>> &mat) {
    int n = mat.size();
    vector<vector<int>> diag(2 * n - 1);

    // Store diagonals
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            diag[i + j].push_back(mat[i][j]);
        }
    }

    // Print result
    for (int d = 0; d < 2 * n - 1; d++) {
        for (int val : diag[d]) {
            cout << val << " ";
        }
    }
}

int main() {
    vector<vector<int>> mat = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    diagonalTraversal(mat);
    return 0;
}


