        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                diag.get(i + j).add(mat[i][j]);
            }
        }

        // Print result
        for (int d = 0; d < 2 * n - 1; d++) {
            for (int val : diag.get(d)) {
                System.out.print(val + " ");
            }
        }
    }

